import React,{useEffect,useMemo,useState}from'react';
import{AGENT_TOPIC_SCOPE_MIN_LENGTH,buildAgentAutomationPayload}from'./agent-admin-settings.mjs';
import{BlogReadingContent}from'./BlogPages.jsx';
import CapabilityTaskPanel from'./CapabilityTaskPanel.jsx';

const defaults={enabled:false,model:'deepseek-flash',intervalHours:24,monthlyArticleLimit:31,topicScope:'人文、历史、地理、科学、游戏与数字创作中的大众知识'};
const defaultBehavior={schemaVersion:'agent-behavior-v1',core:{mission:'发现、研究并向中文读者介绍真正有用或有趣的开放项目，诚实说明证据边界，不把营销包装当成事实。',personality:'好奇、审慎、有判断力；愿意关注小而巧的创意，也不会因为热门术语或夸张名称高估项目。',voice:'使用自然、具体、克制的简体中文，先讲清项目解决什么问题，再解释适合谁以及如何开始。',audience:'对人工智能、数字工具、游戏和开放创作感兴趣的普通中文读者与开发者。'},modules:{editorial:{persona:'像一位好奇但不追逐噱头的科技选题编辑。优先选择能快速看到结果、具有互动或创作空间、解决常见问题，或者实现方式令人意外的项目；所有判断都必须来自候选仓库证据。',comparisonEnabled:true,interestSignals:['可以快速体验','结果直观或可视化','实现方式有创意','解决常见但容易忽略的问题','能够生成或分享作品','适合学习和探索']}}};
const statusLabel={queued:'等待执行',generating:'正在写作',checking:'正在检查',published:'已自动发布',rejected:'检查未通过',failed:'运行失败'};
const runtimeStatusLabel={queued:'等待执行',running:'运行中',waiting:'等待外部结果',succeeded:'运行完成',rejected:'策略拒绝',failed:'运行失败',cancelled:'已取消',uncertain:'结果待确认'};
const runtimeWorkflowLabel={'blog.project.discovery-shadow':'候选发现','blog.project.single.draft-shadow':'私有草稿','blog.project.single':'公开文章','paper.single.semantic-shadow':'论文语义阅读','paper.private.research':'私有论文研究','paper.semantic.follow-up-private':'论文证据追问'};
const runtimeStageLabel={'freeze-brief':'锁定选题简报','freeze-context':'冻结论文分析','plan-queries':'规划检索','search-candidates':'检索候选项目','finalize-candidates':'整理候选清单','select-subject':'选择研究对象','collect-evidence':'采集仓库证据','verify-evidence':'核验证据','resolve-source':'解析论文来源','acquire-source':'获取合法开放全文','verify-eligibility':'验证论文准入','reconstruct-sections':'重建证据页窗','extract-semantics':'提取主张与结果','verify-semantics':'核验结论—证据图','persist-analysis':'保存私有分析','finalize-queue':'完成私有研究队列','answer-question':'生成本文内回答','verify-answer':'核验回答引用','persist-answer':'保存不可变问答','compose':'组织文章','persist-draft':'保存私有草稿',publish:'公开发布'};
const cutoverBlockerLabel={PUBLICATION_OWNER_NOT_LEGACY:'当前发布权不在旧链路',LEGACY_RUN_ACTIVE:'旧链路仍有运行中任务',FOUNDATION_RUN_ACTIVE:'新基座仍有运行中任务',FOUNDATION_RUN_UNCERTAIN:'新基座存在结果待确认任务',FOUNDATION_PUBLIC_WORKFLOW_NOT_ACTIVE:'公开工作流尚未激活',FOUNDATION_PUBLISH_CAPABILITY_MISSING:'缺少公开发布能力',FOUNDATION_AUTO_PUBLISH_POLICY_DISABLED:'自动发布策略尚未允许',PRIVATE_ACCEPTANCE_INCOMPLETE:'尚未取得完整的私有自动验收',PRIVATE_SCHEDULE_EVIDENCE_INCOMPLETE:'旧版策略仍要求私有定时运行证据，请更新服务器'};
const publicRuntimeBlockerLabel={AGENT_BLOG_PUBLIC_RUNTIME_DISABLED:'服务器尚未启用公开执行器',AGENT_BLOG_PUBLIC_RUNTIME_AGENT_MISMATCH:'执行器绑定的机器人不是当前账号',AGENT_BLOG_PUBLICATION_OWNER_NOT_FOUNDATION:'公开发布权尚未交给新基座',AGENT_BLOG_LEGACY_AUTOMATION_STILL_ENABLED:'旧自动发布流程仍处于启用状态',AGENT_BLOG_PUBLIC_RUNTIME_IDENTITY_NOT_READY:'机器人身份或策略配置不完整',AGENT_BLOG_PUBLIC_RUNTIME_CAPABILITIES_NOT_READY:'公开运行所需能力授权不完整',AGENT_BLOG_PUBLIC_RUNTIME_TOOLS_NOT_READY:'GitHub 研究工具合同尚未就绪',AGENT_BLOG_PUBLIC_RUNTIME_WORKFLOWS_NOT_READY:'公开工作流尚未完整激活',AGENT_BLOG_PUBLIC_RUNTIME_SECRET_NOT_READY:'模型 Key 尚未就绪',AGENT_BLOG_PUBLIC_RUNTIME_MODEL_NOT_READY:'所选模型不满足结构化生成要求',AGENT_BLOG_PUBLIC_RUNTIME_PROVIDER_CIRCUIT_OPEN:'模型供应商熔断器未关闭',AGENT_BLOG_PUBLIC_RUNTIME_GITHUB_AUTH_NOT_READY:'GitHub 研究令牌尚未配置',AGENT_BLOG_PUBLIC_RUNTIME_RUN_ACTIVE:'已有新基座任务正在运行',AGENT_BLOG_PUBLIC_RUNTIME_UNCERTAIN:'存在结果待确认的运行',AGENT_BLOG_PUBLIC_RUNTIME_AWAITING_HANDOFF:'存在尚未交接的候选结果',AGENT_BLOG_PUBLIC_RUNTIME_DAILY_LIMIT_REACHED:'今天的公开运行额度已用完',AGENT_BLOG_PUBLIC_RUNTIME_PROVIDER_LIMIT_REACHED:'本月模型调用额度已用完',AGENT_BLOG_PUBLIC_RUNTIME_COST_LIMIT_REACHED:'本月模型费用额度已用完',AGENT_BLOG_PUBLIC_RUNTIME_FAILURE_CIRCUIT_OPEN:'连续失败保护已触发',AGENT_BLOG_PUBLIC_SCHEDULE_DISABLED:'服务器尚未启用公开定时执行器',AGENT_BLOG_PUBLIC_SCHEDULE_MISSING:'尚未登记公开计划',AGENT_BLOG_PUBLIC_SCHEDULE_MODE_INVALID:'当前计划不是公开发布模式',AGENT_BLOG_PUBLIC_SCHEDULE_NOT_ENABLED:'公开计划尚未启用',AGENT_BLOG_PUBLIC_SCHEDULER_HEARTBEAT_STALE:'定时执行器没有新鲜心跳'};
const candidateGateLabel={ARCHIVED_REPOSITORY:'仓库已归档',LICENSE_NOT_VERIFIED:'许可证未核实',PRIMARY_EVIDENCE_INSUFFICIENT:'官方主证据不足',HIGH_RISK_PROJECT:'高风险项目',USE_CASE_UNCLEAR:'用途不够明确',REPOSITORY_IDENTITY_INVALID:'仓库身份无效',SINGLE_PROJECT_PREVIOUSLY_FEATURED:'已做过单项目主角，仅可进入新问题对比'};
const selectionReasonLabel={EVIDENCE_STRONG:'证据充分',USE_CASE_CONCRETE:'使用场景具体',HANDS_ON_TESTABLE:'可以动手验证',READER_VALUE_HIGH:'读者价值较高',NOVELTY_SUFFICIENT:'新鲜度足够',COMPARISON_JUSTIFIED:'具备真实对比关系'};
const selectionScoreLabel={readerValue:'读者价值',handsOnPotential:'动手潜力',novelty:'新鲜度',explainability:'可解释性',evidenceStrength:'证据强度'};
const paperQualityGradeLabel={'trusted-text':'可信文本','limited-text':'受限文本',blocked:'已阻断'};
const paperQualityReasonLabel={EMPTY_TEXT_PAGES:'存在空白文本页',SCANNED_PAGES:'疑似扫描页',LOW_TEXT_DENSITY:'文字密度过低',READING_ORDER_UNCERTAIN:'阅读顺序不可靠',MULTI_COLUMN_LAYOUT:'多栏版面',TABLE_STRUCTURE_UNSUPPORTED:'表格结构未还原',FORMULA_STRUCTURE_UNSUPPORTED:'公式结构未还原',IMAGE_CONTENT_UNREAD:'图片内容未读取',EVIDENCE_COVERAGE_LOW:'证据页覆盖不足'};
const format=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}):'—';
const modelLabel=model=>model.name&&model.name!==model.id?`${model.name}（${model.id}）`:model.id;
const cleanSourceExcerpt=value=>String(value??'').replace(/!\[[^\]]*\]\([^)]*\)/gu,' ').replace(/<img\b[^>]*>/giu,' ').replace(/<[^>]+>/gu,' ').replace(/\[([^\]]+)\]\([^)]*\)/gu,'$1').replace(/&(nbsp|amp|lt|gt|quot|#39);/giu,match=>({nbsp:' ',amp:'&',lt:'<',gt:'>',quot:'"','#39':"'"}[match.slice(1,-1).toLowerCase()]??' ')).replace(/(?:^|\s)[#>*_`~|-]+(?=\s|$)/gu,' ').replace(/\s+/gu,' ').trim();

function DraftPreview({state,onClose}){
  useEffect(()=>{const close=event=>event.key==='Escape'&&onClose();globalThis.addEventListener?.('keydown',close);return()=>globalThis.removeEventListener?.('keydown',close);},[onClose]);
  const draft=state?.data;
  return <div className="agent-draft-preview" role="dialog" aria-modal="true" aria-label="私有草稿预览" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><article className="agent-draft-preview__sheet blog-article"><header><div><span className="kicker">PRIVATE DRAFT · READ ONLY</span><h2>{draft?.title||'私有草稿'}</h2>{draft&&<p>{draft.summary}</p>}</div><button type="button" className="button button--secondary agent-draft-preview__close" onClick={onClose}>关闭</button></header>{state.status==='loading'?<p className="agent-draft-preview__status" role="status">正在读取草稿…</p>:state.status==='error'?<p className="form-error" role="alert">{state.error}</p>:draft&&<><div className="agent-draft-preview__meta"><span>只读预览</span><span>{draft.publicationState==='draft'?'尚未公开':draft.publicationState}</span><span>{format(draft.createdAt)}</span>{draft.researchEvidence&&<span className={draft.researchEvidence.complete?'is-evidence-complete':'is-evidence-incomplete'}>{draft.researchEvidence.complete?'证据覆盖完整':'证据覆盖不完整'} · 引用 {draft.researchEvidence.boundCitationCount}/{draft.researchEvidence.citationCount} · 片段 {draft.researchEvidence.evidenceSpanCount} · 版本 {draft.researchEvidence.sourceVersionCount}</span>}</div><BlogReadingContent article={draft} excerptFormatter={cleanSourceExcerpt} hideFollowUpPrompt/></>}</article></div>;
}

function CandidateGateReport({report}){
  if(!report)return null;
  return <><section className="agent-candidate-gate"><header><strong>候选确定性门禁</strong><span>通过 {report.acceptedCount} · 淘汰 {report.rejectedCount}</span></header><ol>{report.decisions.map(item=><li key={`${item.candidateIndex}-${item.repositoryKey}`} className={item.accepted?'is-accepted':'is-rejected'}><div><strong>{item.repositoryKey||item.repositoryUrl||`候选 ${item.candidateIndex}`}</strong><small>{item.accepted?(item.restrictionCodes?.length?'受限通过':'通过门禁'):'已在模型排序前淘汰'}</small></div><p>{[...(item.reasonCodes||[]),...(item.restrictionCodes||[])].map(code=>candidateGateLabel[code]||code).join(' · ')||'证据、许可和用途门禁均通过'}</p></li>)}</ol></section><RunDecisionAudit decision={report.selectionDecision} usage={report.usageSummary}/></>;
}

function RunDecisionAudit({decision,usage}){
  if(!decision&&!usage)return null;
  return <section className="agent-decision-audit"><header><div><strong>最终选题决策</strong><span>{decision?.mode==='comparison'?'对比研究':decision?.mode==='single'?'单项目研究':'尚未完成选择'}</span></div>{usage&&<small>模型 {usage.providerCalls} 次 · 工具 {usage.toolCalls} 次 · {usage.inputTokens+usage.outputTokens} Token · {usage.costMicrousd} 微美元{usage.wallClockSeconds==null?'':` · ${usage.wallClockSeconds} 秒`}</small>}</header>{decision&&<><h4>{decision.angle}</h4><p>{decision.rationale}</p>{decision.scores&&<dl>{Object.entries(selectionScoreLabel).map(([key,label])=><div key={key}><dt>{label}</dt><dd><b>{decision.scores[key]}</b><span><i style={{width:`${decision.scores[key]}%`}}/></span></dd></div>)}</dl>}<footer>{(decision.decisionReasonCodes||[]).map(code=><span key={code}>{selectionReasonLabel[code]||code}</span>)}{(decision.repositories||[]).map(repository=><code key={repository}>{repository}</code>)}</footer></>}</section>;
}

function PaperFollowUpDialog({state,onClose,onAsk}){
  const[question,setQuestion]=useState(''),[submitting,setSubmitting]=useState(false),[message,setMessage]=useState('');
  useEffect(()=>{const close=event=>event.key==='Escape'&&onClose();globalThis.addEventListener?.('keydown',close);return()=>globalThis.removeEventListener?.('keydown',close);},[onClose]);
  const data=state?.data,answers=data?.answers??[],evidence=useMemo(()=>{const items=new Map();for(const answer of answers)for(const item of answer.evidence??[])items.set(item.id,item);return[...items.values()].sort((a,b)=>a.evidenceIndex-b.evidenceIndex);},[answers]);
  const submit=async event=>{event.preventDefault();const value=question.trim();if(value.length<2||submitting)return;setSubmitting(true);setMessage('');try{await onAsk(value);setQuestion('');}catch(caught){setMessage(caught.message||'追问失败，请稍后重试。');}finally{setSubmitting(false);}};
  return <div className="agent-paper-follow-up" role="dialog" aria-modal="true" aria-label="私有论文证据追问" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><section className="agent-paper-follow-up__sheet"><header><div><span className="kicker">PRIVATE · EVIDENCE BOUND</span><h2>仅根据本文继续追问</h2><p>回答只使用已冻结的论文结论与 EvidenceSpan；不会联网补充，也不会进入公开文章。</p></div><button type="button" className="button button--secondary" onClick={onClose}>关闭</button></header>{state.status==='loading'?<p className="agent-empty" role="status">正在读取私有分析与引用证据…</p>:state.status==='error'?<p className="form-error" role="alert">{state.error}</p>:data&&<><div className="agent-paper-follow-up__paper"><div><strong>{data.title}</strong><span>{(data.authors||[]).join('、')||'作者未记录'}{data.year?` · ${data.year}`:''}</span></div><a href={data.sourceUrl} target="_blank" rel="noreferrer">查看 arXiv 原文 ↗</a></div><div className="agent-paper-follow-up__suggestions">{(data.followUpQuestions||[]).slice(0,4).map(item=><button type="button" key={item} disabled={submitting} onClick={()=>setQuestion(item)}>{item}<small>填入问题 ↓</small></button>)}</div>{answers.length>0&&<div className="agent-paper-follow-up__thread" aria-live="polite">{answers.map(answer=><article key={answer.id}><header><small>运营者提问</small><strong>{answer.question}</strong></header><p>{answer.answer}</p><footer><span className={`agent-state ${answer.uncertainty==='none'?'is-ready':''}`}>{answer.uncertainty==='none'?'证据充分':answer.uncertainty==='bounded'?'证据有限':'证据不足'}</span>{answer.evidence?.length?<span>依据 {answer.evidence.map(item=><a key={`${answer.id}-${item.id}-${item.findingKey}`} href={`#paper-evidence-${item.id}`}>[{item.evidenceIndex}]</a>)}</span>:<span>未引用 EvidenceSpan</span>}<small>{format(answer.createdAt)} · {answer.modelId}</small></footer></article>)}</div>}<form onSubmit={submit}><label htmlFor="paper-follow-up-question">向小墨鱼提问</label><textarea id="paper-follow-up-question" rows="4" maxLength="500" value={question} disabled={submitting} onChange={event=>setQuestion(event.target.value)} placeholder="例如：这篇论文最强的实验结论是什么，证据边界在哪里？"/><div><span>{question.length}/500 · 每天最多 10 次 · 每题至多 1 次模型调用</span><button type="submit" className={`button button--primary${submitting?' is-loading':''}`} disabled={submitting||question.trim().length<2}>{submitting?<><i className="blog-followups__spinner" aria-hidden="true"/>正在核验证据…</>:'发送私有追问'}</button></div></form>{submitting&&<div className="agent-paper-follow-up__progress" role="status"><i/><span><strong>小墨鱼正在本文证据中查找答案</strong><small>回答还要经过 finding 与 EvidenceSpan 的确定性校验</small></span></div>}{message&&<p className="form-error" role="alert">{message}</p>}{evidence.length>0&&<section className="agent-paper-follow-up__evidence"><header><span className="kicker">EVIDENCE SPANS</span><h3>本轮引用片段</h3></header>{evidence.map(item=><article id={`paper-evidence-${item.id}`} key={item.id}><div><b>[{item.evidenceIndex}]</b><span>{item.findingKey} · {item.relation}</span><small>{item.locator?.pages?.length?`第 ${item.locator.pages.join('、')} 页`:'论文片段'}</small></div><blockquote>{item.quoteText}</blockquote><a href={data.sourceUrl} target="_blank" rel="noreferrer">回到论文原文 ↗</a></article>)}</section>}</>}</section></div>;
}

function PaperQualityCard({data,onOpenFollowUp}){
  if(!data)return null;
  const latest=data.latest,counts=data.counts??{},semantic=data.semantic??{},analysis=semantic.latest;
  return <section className="agent-control-card agent-paper-quality"><div className="agent-control-card__title"><div><span className="kicker">PRIVATE PAPER RESEARCH</span><h3>论文阅读基座</h3><p>先用确定性版面门禁筛除不可靠文本，再把公开 arXiv 论文的作者主张、实验结果与小墨鱼推断分层保存。分析只用于私有研究，不进入公开发布。</p></div><span className={`agent-state ${analysis?'is-ready':''}`}>{analysis?'语义阅读已运行':latest?paperQualityGradeLabel[latest.grade]||latest.grade:'尚无验收'}</span></div><div className="agent-paper-quality__grid"><div><small>累计验收</small><strong>{counts.total??0}</strong></div><div><small>可信文本</small><strong>{counts.trusted??0}</strong></div><div><small>语义分析</small><strong>{semantic.total??0}</strong></div><div><small>受限 / 阻断</small><strong>{(counts.limited??0)+(counts.blocked??0)}</strong></div></div>{latest?<div className={`agent-paper-quality__latest is-${latest.grade}`}><div><strong>{latest.title}</strong><span>{paperQualityGradeLabel[latest.grade]||latest.grade} · {latest.parserVersion}</span></div><p>{latest.reasonCodes.length?latest.reasonCodes.map(code=>paperQualityReasonLabel[code]||code).join(' · '):'文字完整、阅读顺序与证据覆盖均通过。'}</p><small>文字覆盖 {Math.round((latest.metrics.textCoverageBp??0)/100)}% · 证据覆盖 {Math.round((latest.metrics.evidenceCoverageBp??0)/100)}% · {format(latest.createdAt)}</small></div>:<p className="agent-empty">尚无论文解析记录；接入论文研究工作流后会在这里显示质量等级与原因。</p>}{analysis&&<div className="agent-paper-semantic-summary"><div><span className="kicker">SEMANTIC LEDGER</span><strong>{analysis.title}</strong><small>{analysis.provider} · {analysis.modelId} · {format(analysis.createdAt)}</small></div><dl><div><dt>结论节点</dt><dd>{analysis.findingCount}</dd></div><div><dt>局限</dt><dd>{analysis.limitationCount}</dd></div><div><dt>可追问</dt><dd>{analysis.followUpQuestionCount}</dd></div></dl><p>已写入不可变结论—证据账本；公开发布权限保持关闭。</p><button type="button" className="button button--primary" onClick={()=>onOpenFollowUp(analysis.id)}>仅根据本文追问</button></div>}</section>;
}

function PaperIntakeCard({api,agentUserId}){
  const[items,setItems]=useState([]),[doi,setDoi]=useState(''),[file,setFile]=useState(null),[fileDoi,setFileDoi]=useState(''),[rights,setRights]=useState('user-owned'),[busy,setBusy]=useState(''),[error,setError]=useState(''),[message,setMessage]=useState('');
  const load=async()=>{try{const response=await api.listAdminAgentPaperIntakes(agentUserId,20);setItems(response.data);}catch(caught){setError(caught.message||'无法读取私有论文收件箱。');}};
  useEffect(()=>{setItems([]);setDoi('');setFile(null);setFileDoi('');setError('');setMessage('');void load();},[agentUserId]);
  const registerDoi=async event=>{event.preventDefault();if(!doi.trim()||busy)return;setBusy('doi');setError('');setMessage('');try{await api.registerAdminAgentPaperDoi(agentUserId,doi.trim());setDoi('');setMessage('DOI 元数据已登记；没有下载或猜测正文。');await load();}catch(caught){setError(caught.message||'DOI 登记失败。');}finally{setBusy('');}};
  const upload=async event=>{event.preventDefault();const form=event.currentTarget;if(!file||busy)return;setBusy('pdf');setError('');setMessage('');try{await api.uploadAdminAgentPaperPdf(agentUserId,file,{rightsAttestation:rights,doi:fileDoi.trim(),requestTimeoutMs:180000});setFile(null);setFileDoi('');form.reset();setMessage('文件已通过隔离、安全与版面门禁并写入私有证据链。');await load();}catch(caught){setError(caught.message||'文件未通过论文收件门禁。');await load();}finally{setBusy('');}};
  const queueIntake=async item=>{setBusy(`queue-${item.id}`);setError('');setMessage('');try{await api.discoverAdminAgentPaper(agentUserId,{kind:'private-intake',intakeId:item.id});setMessage('已按内容哈希和论文标识去重后加入私有研究队列。');}catch(caught){setError(caught.message||'无法加入私有研究队列。');}finally{setBusy('');}};
  return <section className="agent-control-card agent-paper-intake"><div className="agent-control-card__title"><div><span className="kicker">PRIVATE SOURCE INTAKE · R1.6</span><h3>安全资料入口</h3><p>登记 DOI 元数据，或上传你有权使用的 PDF。文件先进入隔离区；脚本、附件、加密、扫描件和不可靠版面会在模型调用前阻断。</p></div><span className="agent-state is-ready">仅私有研究</span></div><div className="agent-paper-intake__forms"><form onSubmit={registerDoi}><strong>DOI 元数据</strong><p>只向 Crossref 请求书目信息，不联网补正文。</p><label>DOI<input value={doi} onChange={event=>setDoi(event.target.value)} placeholder="10.1234/example" maxLength="300"/></label><button className="button button--secondary" disabled={!!busy||doi.trim().length<7}>{busy==='doi'?'登记中…':'登记 DOI'}</button></form><form onSubmit={upload}><strong>用户自有 PDF</strong><p>最大 20 MiB / 80 页；不会执行文档代码或嵌入附件。</p><label>论文文件<input type="file" accept="application/pdf,.pdf" onChange={event=>setFile(event.target.files?.[0]??null)}/></label><label>关联 DOI（可选）<input value={fileDoi} onChange={event=>setFileDoi(event.target.value)} placeholder="10.1234/example" maxLength="300"/></label><label>使用依据<select value={rights} onChange={event=>setRights(event.target.value)}><option value="user-owned">我拥有该文件</option><option value="authorized-use">我获授权用于研究</option><option value="open-license">文件采用开放许可</option></select></label><button className="button button--primary" disabled={!!busy||!file}>{busy==='pdf'?'隔离检查与解析中…':'安全接收 PDF'}</button></form></div>{message&&<p className="form-success" role="status">{message}</p>}{error&&<p className="form-error" role="alert">{error}</p>}<div className="agent-paper-intake__ledger"><header><strong>不可变收件记录</strong><button type="button" className="button button--secondary" onClick={load}>刷新</button></header>{items.length?<ol>{items.map(item=>{const capability=item.security?.layoutCapability,quality=item.security?.parseQuality;return <li key={item.id} className={`is-${item.status}`}><div><strong>{item.filename||item.security?.metadata?.title||item.doi}</strong><span>{item.kind==='doi-metadata'?'DOI 元数据':item.status==='accepted'?'PDF 已接收':'PDF 已阻断'} · {format(item.createdAt)}</span></div><p>{item.failureCode||quality?.reasonCodes?.join(' · ')||'安全扫描与证据归档均已完成。'}</p>{capability&&<small>版面：{capability.grade} · 原生文字 {capability.pageKinds.textNative}/{capability.pageCount} 页 · 多栏 {capability.pageKinds.multiColumn} · 表格风险 {capability.pageKinds.tableRisk} · 公式风险 {capability.pageKinds.formulaRisk}</small>}{item.evidencePreview?.length>0&&<details><summary>查看证据预览（{item.evidencePreview.length}）</summary>{item.evidencePreview.map(span=><blockquote key={span.id}>{span.quoteText}</blockquote>)}</details>}{item.status==='accepted'&&<button type="button" className="button button--secondary" disabled={!!busy} onClick={()=>queueIntake(item)}>{busy===`queue-${item.id}`?'正在去重…':'加入私有研究队列'}</button>}</li>;})}</ol>:<p className="agent-empty">尚无私有 DOI 或文件收件记录。</p>}</div></section>;
}

function PaperResearchOperationsCard({api,agentUserId}){
  const[data,setData]=useState(null),[busy,setBusy]=useState(''),[reason,setReason]=useState(''),[error,setError]=useState(''),[message,setMessage]=useState('');
  const load=async()=>{try{const response=await api.getAdminAgentPaperResearchOperations(agentUserId);setData(response.data);setError('');}catch(caught){setError(caught.message||'无法读取论文研究运行状态。');}};
  useEffect(()=>{setData(null);setReason('');setError('');setMessage('');void load();const timer=setInterval(()=>void load(),30000);return()=>clearInterval(timer);},[agentUserId]);
  const recover=async candidate=>{if(reason.trim().length<10||busy)return;setBusy(candidate.executionId);setError('');setMessage('');try{await api.recoverAdminAgentPaperResearchExpiredStage(agentUserId,candidate.executionId,reason.trim());setReason('');setMessage('过期租约已由通用 Runtime 安全处理；操作原因和结果已写入不可变审计。');await load();}catch(caught){setError(caught.message||'无法恢复该阶段；有效租约不会被强制抢占。');}finally{setBusy('');}};
  const statusLabel={ready:'运行正常',degraded:'需要关注',blocked:'运行阻断'};
  const errorLabel={source:'来源',quality:'质量',provider:'模型',runtime:'运行时',policy:'策略',unknown:'未分类'};
  const age=value=>value?value>=3600000?`${Math.round(value/3600000)} 小时`:value>=60000?`${Math.round(value/60000)} 分钟`:`${Math.round(value/1000)} 秒`:'—';
  return <section className="agent-control-card agent-paper-operations"><div className="agent-control-card__title"><div><span className="kicker">RESEARCH OPERATIONS · R1.9</span><h3>论文研究运行状态</h3><p>读取通用 Runtime 的持久心跳、租约、积压、阶段耗时、预算与错误事实；这里不创建第二套任务系统。</p></div><div className="agent-paper-operations__heading"><span className={`agent-state ${data?.health==='ready'?'is-ready':data?.health==='blocked'?'is-blocked':''}`}>{statusLabel[data?.health]||'正在读取'}</span><button type="button" className="button button--secondary" onClick={load}>刷新</button></div></div>{message&&<p className="form-success" role="status">{message}</p>}{error&&<p className="form-error" role="alert">{error}</p>}{data&&<><div className="agent-paper-operations__facts"><article><small>研究 Worker</small><strong>{data.workers.filter(item=>item.fresh).length}/{data.workers.length} 在线</strong><span>{data.workers[0]?`最近心跳 ${age(data.workers[0].heartbeatAgeMs)}前`:'未登记研究 worker'}</span></article><article><small>队列积压</small><strong>{data.backlog.queuedItems} 项</strong><span>最老等待 {age(data.backlog.oldestWaitingAgeMs)}</span></article><article><small>活跃运行</small><strong>{data.backlog.activeExecutions} 个</strong><span>过期租约 {data.redriveCandidates.length} 个</span></article><article><small>本月模型消耗</small><strong>{data.monthlyBudget.providerCalls} 次</strong><span>{data.monthlyBudget.inputTokens.toLocaleString()} 入 / {data.monthlyBudget.outputTokens.toLocaleString()} 出</span></article></div>{data.blockers.length>0&&<div className="agent-paper-operations__blockers"><strong>当前门禁</strong><ul>{data.blockers.map(item=><li key={item.code}>{item.code}{item.count?` · ${item.count}`:''}</li>)}</ul></div>}<div className="agent-paper-operations__grid"><section><header><strong>阶段耗时（近 30 天）</strong></header>{data.stageMetrics.length?<ol>{data.stageMetrics.map(item=><li key={item.stageKey}><span>{item.stageKey}</span><strong>P95 {age(item.p95Ms)}</strong><small>{item.succeeded}/{item.samples} 成功</small></li>)}</ol>:<p className="agent-empty">尚无完成阶段样本。</p>}</section><section><header><strong>错误分类（近 30 天）</strong></header><ol>{Object.entries(data.errors.categories).map(([key,value])=><li key={key}><span>{errorLabel[key]||key}</span><strong>{value}</strong></li>)}</ol></section></div>{data.redriveCandidates.length>0&&<div className="agent-paper-operations__recovery"><header><div><strong>受控恢复过期阶段</strong><p>只处理租约已过期或执行已超时的阶段；有效租约、外部动作不确定态和预算限制不会被绕过。</p></div></header><label>操作原因<textarea value={reason} onChange={event=>setReason(event.target.value)} maxLength="1000" placeholder="至少 10 个字符，说明为何现在恢复以及已确认的现场情况。"/></label><ol>{data.redriveCandidates.map(item=><li key={item.id}><div><strong>{item.stageKey}</strong><span>运行 {item.runId.slice(0,8)} · 尝试 {item.attempt}/{item.maxAttempts} · 过期 {age(item.stageAgeMs)}</span></div><button type="button" className="button button--secondary" disabled={!!busy||reason.trim().length<10} onClick={()=>recover(item)}>{busy===item.executionId?'正在安全恢复…':'恢复过期阶段'}</button></li>)}</ol></div>}</>}</section>;
}

function PaperResearchLifecycleCard({api,agentUserId}){
  const[data,setData]=useState(null),[policy,setPolicy]=useState(null),[preview,setPreview]=useState(null),[reason,setReason]=useState(''),[busy,setBusy]=useState(''),[error,setError]=useState(''),[message,setMessage]=useState('');
  const load=async()=>{try{const response=await api.getAdminAgentPaperResearchOperations(agentUserId);setData(response.data);setPolicy(current=>current??response.data.policy);setError('');}catch(caught){setError(caught.message||'无法读取运维策略。');}};
  useEffect(()=>{setData(null);setPolicy(null);setPreview(null);setReason('');setMessage('');setError('');void load();},[agentUserId]);
  const save=async event=>{event.preventDefault();if(!policy||busy)return;setBusy('policy');setError('');setMessage('');try{await api.setAdminAgentPaperResearchOperationsPolicy(agentUserId,{...policy,workerHeartbeatSeconds:Number(policy.workerHeartbeatSeconds),staleStageSeconds:Number(policy.staleStageSeconds),oldestBacklogSeconds:Number(policy.oldestBacklogSeconds),metricRetentionDays:Number(policy.metricRetentionDays),weeklyReportWeekday:Number(policy.weeklyReportWeekday)});setMessage('运维策略新版本已保存；常驻 Worker 会在下一个巡检周期自动采用。');setPolicy(null);await load();}catch(caught){setError(caught.message||'运维策略保存失败。');}finally{setBusy('');}};
  const inspectRetention=async()=>{setBusy('preview');setError('');try{const response=await api.previewAdminAgentPaperResearchRetention(agentUserId);setPreview(response.data);}catch(caught){setError(caught.message||'无法预览保留策略。');}finally{setBusy('');}};
  const applyRetention=async()=>{if(reason.trim().length<10||busy)return;setBusy('retention');setError('');setMessage('');try{const response=await api.applyAdminAgentPaperResearchRetention(agentUserId,reason.trim());setMessage(`已清理 ${response.data.deletedMetricSnapshots} 条过期派生快照；论文、证据、运行和审计记录未触碰。`);setReason('');setPreview(null);await load();}catch(caught){setError(caught.message||'保留策略执行失败。');}finally{setBusy('');}};
  const weekday=['','周一','周二','周三','周四','周五','周六','周日'];
  return <section className="agent-control-card agent-paper-lifecycle"><div className="agent-control-card__title"><div><span className="kicker">RESEARCH RELIABILITY · R1.10</span><h3>告警、周报与数据保留</h3><p>巡检运行在同一个论文 Worker 中，不依赖本页常开。研究事实永久保留，只允许清理派生健康快照。</p></div><span className={`agent-state ${data?.alerts?.some(item=>item.status==='open')?'is-blocked':'is-ready'}`}>{data?.alerts?.filter(item=>item.status==='open').length??0} 个打开告警</span></div>{message&&<p className="form-success" role="status">{message}</p>}{error&&<p className="form-error" role="alert">{error}</p>}{policy&&<form className="agent-paper-lifecycle__policy" onSubmit={save}><label><span>启用巡检</span><input type="checkbox" checked={policy.enabled} onChange={event=>setPolicy({...policy,enabled:event.target.checked})}/></label><label>Worker 心跳阈值（秒）<input type="number" min="60" max="3600" value={policy.workerHeartbeatSeconds} onChange={event=>setPolicy({...policy,workerHeartbeatSeconds:event.target.value})}/></label><label>阶段停滞阈值（秒）<input type="number" min="300" max="86400" value={policy.staleStageSeconds} onChange={event=>setPolicy({...policy,staleStageSeconds:event.target.value})}/></label><label>积压告警阈值（秒）<input type="number" min="900" max="604800" value={policy.oldestBacklogSeconds} onChange={event=>setPolicy({...policy,oldestBacklogSeconds:event.target.value})}/></label><label>派生快照保留（天）<input type="number" min="30" max="730" value={policy.metricRetentionDays} onChange={event=>setPolicy({...policy,metricRetentionDays:event.target.value})}/></label><label><span>生成运营周报</span><input type="checkbox" checked={policy.weeklyReportEnabled} onChange={event=>setPolicy({...policy,weeklyReportEnabled:event.target.checked})}/></label><label><span>邮件告警与周报</span><input type="checkbox" checked={policy.emailNotificationsEnabled} onChange={event=>setPolicy({...policy,emailNotificationsEnabled:event.target.checked})}/></label><label>周报日<select value={policy.weeklyReportWeekday} onChange={event=>setPolicy({...policy,weeklyReportWeekday:event.target.value})}>{weekday.slice(1).map((item,index)=><option key={item} value={index+1}>{item}</option>)}</select></label><label>周报时间<input type="time" value={policy.weeklyReportLocalTime} onChange={event=>setPolicy({...policy,weeklyReportLocalTime:event.target.value})}/></label><label>时区<input value={policy.timezone} maxLength="64" onChange={event=>setPolicy({...policy,timezone:event.target.value})}/></label><button className="button button--primary" disabled={!!busy}>{busy==='policy'?'保存中…':`保存策略 v${policy.version??1}`}</button></form>}{data&&<div className="agent-paper-lifecycle__grid"><section><header><strong>持久告警</strong><span>{data.alerts.filter(item=>item.status==='open').length} 打开</span></header>{data.alerts.length?<ol>{data.alerts.slice(0,8).map(item=><li key={item.id} className={`is-${item.status}`}><div><strong>{item.code}</strong><span>{item.status==='open'?'处理中':'已恢复'} · {item.occurrences} 次</span></div><small>{format(item.lastSeenAt)}</small></li>)}</ol>:<p className="agent-empty">尚无告警事件。</p>}</section><section><header><strong>运营周报</strong><span>{weekday[data.policy.weeklyReportWeekday]} {data.policy.weeklyReportLocalTime}</span></header>{data.weeklyReports.length?<ol>{data.weeklyReports.slice(0,4).map(item=><li key={item.id}><div><strong>{format(item.weekStartedAt)} 起</strong><span>{item.report.health} · 告警 {item.report.blockers?.length??0}</span></div><small>{format(item.createdAt)}</small></li>)}</ol>:<p className="agent-empty">到达计划时间后由服务端自动生成。</p>}</section></div>}{data&&<section className="agent-paper-lifecycle__retention"><header><div><strong>保留策略</strong><p>{data.retention.metricSnapshots} 条派生快照；受保护记录不会被自动或人工清理。</p></div><button type="button" className="button button--secondary" disabled={!!busy} onClick={inspectRetention}>{busy==='preview'?'计算中…':'预览清理'}</button></header><div className="agent-paper-lifecycle__protected">永久保留：{data.retention.protectedRecords.join(' · ')}</div>{preview&&<><p className="agent-paper-lifecycle__preview">截止 {format(preview.cutoffAt)} 前可清理 <strong>{preview.deletableMetricSnapshots}</strong> 条派生快照。</p><label>执行原因<textarea maxLength="1000" value={reason} onChange={event=>setReason(event.target.value)} placeholder="至少 10 个字符，说明本次清理原因。"/></label><button type="button" className="danger-button" disabled={!!busy||reason.trim().length<10} onClick={applyRetention}>{busy==='retention'?'正在清理…':'执行已预览清理'}</button></>}</section>}</section>;
}

function PaperDiscoveryCard({api,agentUserId}){
  const[kind,setKind]=useState('doi'),[doi,setDoi]=useState(''),[arxivId,setArxivId]=useState(''),[title,setTitle]=useState(''),[author,setAuthor]=useState(''),[runs,setRuns]=useState([]),[queue,setQueue]=useState([]),[executions,setExecutions]=useState([]),[busy,setBusy]=useState(''),[error,setError]=useState(''),[message,setMessage]=useState('');
  const latestExecution=useMemo(()=>{const map=new Map();for(const item of executions)if(!map.has(item.queueItemId))map.set(item.queueItemId,item);return map;},[executions]);
  const load=async()=>{setError('');const[discoveries,items,research]=await Promise.allSettled([api.listAdminAgentPaperDiscoveries(agentUserId,12),api.listAdminAgentPaperResearchQueue(agentUserId,50),api.listAdminAgentPaperResearchExecutions(agentUserId,50)]);if(discoveries.status==='fulfilled')setRuns(discoveries.value.data);if(items.status==='fulfilled')setQueue(items.value.data);if(research.status==='fulfilled')setExecutions(research.value.data);const failed=[discoveries,items,research].find(item=>item.status==='rejected');if(failed)setError(failed.reason?.message||'无法读取论文发现、队列与执行记录。');};
  useEffect(()=>{setRuns([]);setQueue([]);setExecutions([]);setError('');setMessage('');void load();},[agentUserId]);
  const submit=async event=>{event.preventDefault();if(busy)return;const body=kind==='doi'?{kind,doi:doi.trim()}:kind==='arxiv'?{kind,arxivId:arxivId.trim()}:{kind,title:title.trim(),author:author.trim()};setBusy('discover');setError('');setMessage('');try{const response=await api.discoverAdminAgentPaper(agentUserId,body);const blocked=response.data.candidates.filter(item=>item.queue?.state==='blocked').length;setMessage(blocked?`发现已完成；${blocked} 个候选因身份不确定进入阻断队列。`:'发现已完成，确定性身份候选已进入私有研究队列。');await load();}catch(caught){setError(caught.message||'论文发现失败。');}finally{setBusy('');}};
  const changeState=async(item,state)=>{setBusy(item.id);setError('');try{await api.setAdminAgentPaperResearchQueueState(agentUserId,item.id,{state,reason:state==='paused'?'管理员暂停私有研究':'管理员恢复私有研究'});await load();}catch(caught){setError(caught.message||'队列状态切换失败。');}finally{setBusy('');}};
  const startResearch=async item=>{setBusy(`start-${item.id}`);setError('');setMessage('');try{await api.startAdminAgentPaperResearchExecution(agentUserId,item.id);setMessage('私有论文研究已进入持久队列；页面可安全关闭，worker 会继续执行。');await load();}catch(caught){setError(caught.message||'无法启动私有论文研究。');}finally{setBusy('');}};
  const retryResearch=async execution=>{setBusy(`retry-${execution.id}`);setError('');try{await api.retryAdminAgentPaperResearchExecution(agentUserId,execution.id);setMessage('已创建新的可审计尝试，旧失败记录保持不变。');await load();}catch(caught){setError(caught.message||'无法重试本次研究。');}finally{setBusy('');}};
  const cancelResearch=async execution=>{if(!globalThis.confirm?.('取消只会终止私有研究运行，不会删除论文、证据或既有审计记录。确定继续？'))return;setBusy(`cancel-${execution.id}`);setError('');try{await api.cancelAdminAgentPaperResearchExecution(agentUserId,execution.id,'管理员在研究控制台取消运行');await load();}catch(caught){setError(caught.message||'当前阶段正在执行，暂不能安全取消。');}finally{setBusy('');}};
  const decisionLabel={"exact-version":'精确版本',"exact-identity":'精确论文',"new-identity-candidate":'新论文候选',"possible-match":'可能重复，已阻断',conflict:'身份冲突，已阻断',blocked:'已阻断'};
  const executionLabel={queued:'等待 worker',running:'正在研究',blocked:'缺少合法正文',succeeded:'研究完成',failed:'运行失败',cancelled:'已取消'};
  return <section className="agent-control-card agent-paper-discovery"><div className="agent-control-card__title"><div><span className="kicker">PRIVATE PAPER RESEARCH · R1.8</span><h3>论文发现与可恢复研究队列</h3><p>按 DOI、arXiv 或标题作者发现论文。只有合法开放全文会自动进入模型研究；元数据和用户文件默认失败关闭，绝不绕过付费墙或暗中外发。</p></div><span className="agent-state is-ready">持久执行 · 零发布</span></div><form className="agent-paper-discovery__form" onSubmit={submit}><label>发现方式<select value={kind} onChange={event=>setKind(event.target.value)}><option value="doi">DOI 精确发现</option><option value="arxiv">arXiv 精确发现</option><option value="title-author">标题与作者搜索</option></select></label>{kind==='doi'?<label>DOI<input maxLength="300" value={doi} onChange={event=>setDoi(event.target.value)} placeholder="10.1234/example"/></label>:kind==='arxiv'?<label>arXiv ID<input maxLength="300" value={arxivId} onChange={event=>setArxivId(event.target.value)} placeholder="2401.12345"/></label>:<><label>论文标题<input maxLength="1000" value={title} onChange={event=>setTitle(event.target.value)} placeholder="完整或主要标题"/></label><label>作者<input maxLength="300" value={author} onChange={event=>setAuthor(event.target.value)} placeholder="至少一位作者"/></label></>}<button className="button button--primary" disabled={!!busy||(kind==='doi'&&doi.trim().length<7)||(kind==='arxiv'&&arxivId.trim().length<5)||(kind==='title-author'&&(!title.trim()||!author.trim()))}>{busy==='discover'?'正在核验身份…':'发现并加入私有队列'}</button></form>{message&&<p className="form-success" role="status">{message}</p>}{error&&<p className="form-error" role="alert">{error}</p>}<div className="agent-paper-discovery__grid"><section><header><strong>最近发现判定</strong><button className="button button--secondary" type="button" onClick={load}>刷新</button></header>{runs.length?<ol>{runs.flatMap(run=>run.candidates.map(candidate=><li key={candidate.id}><div><strong>{candidate.title}</strong><span>{decisionLabel[candidate.resolution?.decision]||candidate.resolution?.decision}</span></div><p>{candidate.authors.join('、')} · {candidate.publicationYear||'年份未知'}</p><small>{candidate.resolution?.explanation?.reason||'等待身份判定'} · 模型合并：否</small></li>))}</ol>:<p className="agent-empty">尚无论文发现批次。</p>}</section><section><header><strong>私有研究队列</strong><span>{queue.filter(item=>item.state==='queued').length} 项待研究</span></header>{queue.length?<ol>{queue.map(item=>{const execution=latestExecution.get(item.id),active=['queued','running'].includes(execution?.status);return <li key={item.id} className={`is-${execution?.status||item.state}`}><div><strong>{item.candidate.title}</strong><span>{execution?executionLabel[execution.status]||execution.status:item.state==='queued'?'待研究':item.state==='paused'?'已暂停':item.state==='blocked'?'待核验':item.state==='completed'?'已完成':'已拒绝'}</span></div><p>{execution?.errorCode||item.reason}</p>{execution&&<small>阶段 {execution.stageKey} · 尝试 {execution.attemptNumber} · {format(execution.updatedAt)}</small>}<div className="agent-paper-research-actions">{item.state==='queued'&&!execution&&<button type="button" className="button button--primary" disabled={!!busy} onClick={()=>startResearch(item)}>{busy===`start-${item.id}`?'正在入队…':'开始私有研究'}</button>}{['failed','blocked','cancelled'].includes(execution?.status)&&item.state==='queued'&&<button type="button" className="button button--primary" disabled={!!busy} onClick={()=>retryResearch(execution)}>{busy===`retry-${execution.id}`?'正在重试…':'新建重试'}</button>}{active&&<button type="button" className="button button--secondary" disabled={!!busy} onClick={()=>cancelResearch(execution)}>{busy===`cancel-${execution.id}`?'正在取消…':'取消运行'}</button>}{!execution&&['queued','paused'].includes(item.state)&&<button type="button" className="button button--secondary" disabled={!!busy} onClick={()=>changeState(item,item.state==='queued'?'paused':'queued')}>{busy===item.id?'保存中…':item.state==='queued'?'暂停':'恢复'}</button>}</div></li>;})}</ol>:<p className="agent-empty">研究队列为空。</p>}</section></div></section>;
}

export default function AgentAdmin({api,go,hostIdentity,hostAdapter}){
  const[agents,setAgents]=useState([]),[selectedId,setSelectedId]=useState(null),[runs,setRuns]=useState([]),[runtimeRuns,setRuntimeRuns]=useState([]),[runtimeOverview,setRuntimeOverview]=useState(null),[runtimeDetails,setRuntimeDetails]=useState({}),[draftPreview,setDraftPreview]=useState(null),[paperFollowUp,setPaperFollowUp]=useState(null),[cutover,setCutover]=useState({status:'idle',data:null,error:''}),[cutoverReason,setCutoverReason]=useState(''),[settings,setSettings]=useState(defaults),[behavior,setBehavior]=useState(defaultBehavior),[behaviorVersion,setBehaviorVersion]=useState(null),[apiKey,setApiKey]=useState(''),[models,setModels]=useState([]),[modelsState,setModelsState]=useState('idle'),[modelsError,setModelsError]=useState(''),[busy,setBusy]=useState(''),[message,setMessage]=useState(''),[error,setError]=useState('');
  const selected=useMemo(()=>agents.find(item=>item.agentUserId===selectedId)??null,[agents,selectedId]);
  const visibleRuntimeRuns=useMemo(()=>{const foundationOwnsPublication=cutover.data?.owner?.activePublisher==='foundation';return runtimeRuns.filter(run=>run.workflowKey==='paper.single.semantic-shadow'||run.workflowKey==='paper.private.research'||run.workflowKey==='paper.semantic.follow-up-private'||(foundationOwnsPublication?run.workflowKey==='blog.project.single':run.workflowKey==='blog.project.single'||run.workflowKey==='blog.project.single.draft-shadow'||(run.workflowKey==='blog.project.discovery-shadow'&&(!run.targetRunId||run.status!=='succeeded'))));},[runtimeRuns,cutover.data?.owner?.activePublisher]);
  const load=async()=>{try{const response=await api.listAdminAgents(),items=response.data;setAgents(items);setSelectedId(current=>current&&items.some(item=>item.agentUserId===current)?current:items[0]?.agentUserId??null);}catch(caught){setError(caught.message||'无法读取机器人。');}};
  const loadRuns=async(id,includeLegacy=cutover.data?.owner?.activePublisher!=='foundation')=>{if(!id){setRuns([]);setRuntimeRuns([]);setRuntimeOverview(null);return;}const legacyRequest=includeLegacy?api.listAdminAgentBlogRuns(id):Promise.resolve({data:[]}),[legacy,runtime,overview]=await Promise.allSettled([legacyRequest,api.listAdminAgentRuntimeRuns(id,50),api.getAdminAgentRuntimeOverview(id)]);if(legacy.status==='fulfilled')setRuns(legacy.value.data);if(runtime.status==='fulfilled')setRuntimeRuns(runtime.value.data);if(overview.status==='fulfilled')setRuntimeOverview(overview.value.data);const failed=[legacy,runtime,overview].find(result=>result.status==='rejected');if(failed)setError(failed.reason?.message||'无法读取运行记录。');};
  const loadCutover=async id=>{if(!id){setCutover({status:'idle',data:null,error:''});return;}setCutover(current=>({...current,status:'loading',error:''}));try{const response=await api.getAdminAgentPublicationCutoverPreflight(id);setCutover({status:'ready',data:response.data,error:''});}catch(caught){setCutover({status:'error',data:null,error:caught.message||'无法读取发布权状态。'});}};
  const toggleRuntimeDetails=async run=>{const current=runtimeDetails[run.id];if(current?.data){setRuntimeDetails(items=>({...items,[run.id]:{...items[run.id],expanded:!items[run.id].expanded}}));return;}setRuntimeDetails(items=>({...items,[run.id]:{expanded:true,status:'loading',data:null,error:''}}));try{const response=await api.getAdminAgentRuntimeTimeline(selected.agentUserId,run.id);setRuntimeDetails(items=>({...items,[run.id]:{expanded:true,status:'ready',data:response.data,error:''}}));}catch(caught){setRuntimeDetails(items=>({...items,[run.id]:{expanded:true,status:'error',data:null,error:caught.message||'无法读取阶段记录。'}}));}};
  const openFoundationDraft=async articleId=>{setDraftPreview({status:'loading',data:null,error:''});try{const response=await api.getAdminAgentFoundationDraft(selected.agentUserId,articleId);setDraftPreview({status:'ready',data:response.data,error:''});}catch(caught){setDraftPreview({status:'error',data:null,error:caught.message||'无法读取私有草稿。'});}};
  const openPaperFollowUp=async analysisId=>{setPaperFollowUp({status:'loading',analysisId,data:null,error:''});try{const response=await api.getAdminAgentPaperAnalysis(selected.agentUserId,analysisId);setPaperFollowUp({status:'ready',analysisId,data:response.data,error:''});}catch(caught){setPaperFollowUp({status:'error',analysisId,data:null,error:caught.message||'无法读取论文分析。'});}};
  const askPaperFollowUp=async question=>{const analysisId=paperFollowUp.analysisId;const response=await api.askAdminAgentPaperFollowUp(selected.agentUserId,analysisId,question,{requestTimeoutMs:360000});setPaperFollowUp(current=>({...current,status:'ready',data:{...current.data,answers:[...(current.data?.answers??[]),response.data]}}));return response.data;};
  const loadBehavior=async id=>{if(!id)return;try{const response=await api.getAdminAgentBehaviorProfile(id);setBehavior(response.data.profile);setBehaviorVersion(response.data.version);}catch(caught){setError(caught.message||'无法读取机器人人格。');}};
  const applyModels=items=>{const safe=Array.isArray(items)?items:[];setModels(safe);setSettings(current=>safe.some(model=>model.id===current.model)?current:{...current,model:safe.find(model=>model.id==='deepseek-flash')?.id??safe[0]?.id??current.model});};
  const loadModels=async id=>{if(!id)return;setModelsState('loading');setModelsError('');try{const response=await api.listAdminAgentProviderModels(id);applyModels(response.data.models);setModelsState('ready');}catch(caught){setModels([]);setModelsState('error');setModelsError(caught.message||'无法读取可用模型。');}};
  useEffect(()=>{void load();},[api]);
  useEffect(()=>{if(!selected)return;setSettings({...defaults,...selected.automation});setBehavior(defaultBehavior);setBehaviorVersion(null);setRuntimeDetails({});setDraftPreview(null);setPaperFollowUp(null);setCutoverReason('');setModels([]);setModelsError('');setModelsState(selected.providerKey.configured?'loading':'idle');void loadCutover(selected.agentUserId);void loadBehavior(selected.agentUserId);if(selected.providerKey.configured)void loadModels(selected.agentUserId);},[selected?.agentUserId]);
  useEffect(()=>{const owner=cutover.data?.owner?.activePublisher;if(!selected||!owner)return;const includeLegacy=owner!=='foundation';if(!includeLegacy)setRuns([]);void loadRuns(selected.agentUserId,includeLegacy);const timer=setInterval(()=>void loadRuns(selected.agentUserId,includeLegacy),5000);return()=>clearInterval(timer);},[selected?.agentUserId,cutover.data?.owner?.activePublisher]);
  const action=async(kind,work)=>{setBusy(kind);setMessage('');setError('');try{const result=await work();setMessage(kind==='key'?'Key 已验证并加密保存，可用模型已同步。':kind==='settings'?'自动发布策略已保存。':kind==='behavior'?'机器人人格新版本已激活；已排队任务仍使用创建时锁定的版本。':kind==='run'?'任务已进入自动写作队列。':kind==='foundation-run'?'新基座任务已安全提前到现在，将由本机调度器领取执行。':kind==='public-schedule-enable'?'每天 10:00 的新基座计划已启用。':kind==='public-schedule-disable'?'新基座计划已暂停；执行器保持在线，可随时从后台恢复。':kind.startsWith('withdraw-')?'自动发布文章已撤回。':'操作已完成。');setApiKey('');await load();if(selectedId)await loadRuns(selectedId);return result;}catch(caught){setError(caught.message||'操作失败。');return null;}finally{setBusy('');}};
  const provision=()=>action('provision',()=>api.createAdminAgent({provisionKey:'official-mooyu-researcher-v1',displayName:'小墨鱼',handle:'mooyu-researcher',badgeLabel:'AI 助手',operatorLabel:'由墨鱼工坊运营',capabilities:['blog:auto-publish'],metadata:{purpose:'official-journal',personaVersion:1}}));
  const saveKey=()=>action('key',async()=>{const response=await api.setAdminAgentProviderKey(selected.agentUserId,apiKey.trim());applyModels(response.data.models);setModelsState('ready');return response;});
  const saveSettings=()=>{let payload;try{payload=buildAgentAutomationPayload(settings);}catch(caught){setMessage('');setError(caught.message);return;}return action('settings',()=>api.updateAdminAgentBlogAutomation(selected.agentUserId,payload));};
  const saveBehavior=()=>action('behavior',async()=>{const response=await api.updateAdminAgentBehaviorProfile(selected.agentUserId,behavior);setBehavior(response.data.profile);setBehaviorVersion(response.data.version);return response;});
  const changePublicationOwner=async()=>{const state=cutover.data,reason=cutoverReason.trim();if(!state?.owner||reason.length<10)return;if(!globalThis.confirm?.('切换后旧流程与私有计划会立即停止，公开执行仍需单独启动。确定继续？'))return;const result=await action('publication-cutover',()=>api.cutoverAdminAgentPublication(selected.agentUserId,{expectedGeneration:state.owner.generation,reason}));if(result)setCutoverReason('');await loadCutover(selected.agentUserId);};
  const setPublicSchedule=async enabled=>{const result=await action(enabled?'public-schedule-enable':'public-schedule-disable',()=>api.setAdminAgentPublicSchedule(selected.agentUserId,enabled));if(result)await loadRuns(selected.agentUserId);};
  const runFoundationNow=async()=>{const result=await action('foundation-run',()=>api.runAdminAgentFoundationNow(selected.agentUserId));if(result)await loadRuns(selected.agentUserId);};
  const setCore=(key,value)=>setBehavior(current=>({...current,core:{...current.core,[key]:value}}));
  const setEditorial=(key,value)=>setBehavior(current=>({...current,modules:{...current.modules,editorial:{...current.modules.editorial,[key]:value}}}));
  const topicScopeLength=settings.topicScope.trim().length;
  const modelHint=modelsState==='loading'?'正在从 DeepSeek 读取可用模型…':modelsState==='error'?modelsError:models.length?`已同步 ${models.length} 个可用模型；列表由 DeepSeek 返回。`:selected?.providerKey.configured?'尚未同步模型列表。':'保存并验证 Key 后即可选择模型。';
  const publicationOwner=cutover.data?.owner;
  const publicationEvidence=cutover.data?.evidence;
  const publicationIsFoundation=publicationOwner?.activePublisher==='foundation';
  const publicationReasonReady=cutoverReason.trim().length>=10;
  const publicOperations=runtimeOverview?.publicOperations;
  const publicSchedulerOnline=Boolean(publicOperations?.scheduler.configured&&publicOperations?.scheduler.workerLive&&runtimeOverview?.schedule?.enabled&&!runtimeOverview?.schedule?.suspendedAt);
  const publicQuotaSpent=Boolean(publicOperations?.scheduler.blockers?.includes('AGENT_BLOG_PUBLIC_RUNTIME_DAILY_LIMIT_REACHED'));
  const actionablePublicBlockers=(publicOperations?.scheduler.blockers??[]).filter(code=>!(publicSchedulerOnline&&code==='AGENT_BLOG_PUBLIC_RUNTIME_DAILY_LIMIT_REACHED'));
  return <section className="agent-admin">
    <header className="agent-admin__head"><div><span className="kicker">AUTONOMOUS AGENTS</span><h2>小墨鱼控制台</h2><p>统一管理作者身份、模型 Key、人格、发布权和每天 10 点的全自动运行；无需逐篇确认。</p></div>{!agents.length&&<button className="button button--primary" disabled={!!busy} onClick={provision}>{busy==='provision'?'创建中…':'创建“小墨鱼”'}</button>}</header>
    {message&&<p className="admin-notice" role="status">{message}</p>}{error&&<p className="form-error" role="alert">{error}</p>}
    {agents.length>0&&<div className="agent-admin__layout">
      <aside className="agent-admin__list">{agents.map(agent=><button key={agent.agentUserId} className={agent.agentUserId===selectedId?'is-active':''} onClick={()=>setSelectedId(agent.agentUserId)}><strong>{agent.displayName}</strong><span>@{agent.handle}</span><small>{agent.status==='active'?'运行身份正常':'已暂停'} · {agent.providerKey.configured?`Key ····${agent.providerKey.lastFour}`:'未设置 Key'}</small></button>)}</aside>
      {selected&&<main className="agent-admin__body">
        <section className="agent-identity-card"><div><h3>{selected.displayName}</h3><p>@{selected.handle} · {selected.agentDisclosure.operatorLabel}</p></div><button className="button button--secondary" onClick={()=>go(`/u/${selected.handle}`)}>查看公开主页</button></section>
        <CapabilityTaskPanel api={api} agentUserId={selected.agentUserId} hostIdentity={hostIdentity} hostAdapter={hostAdapter}/>
        <section className="agent-control-card agent-behavior-card"><div className="agent-control-card__title"><div><span className="kicker">BEHAVIOR PROFILE</span><h3>人格与行为</h3><p>这是机器人的通用人格底座。编辑模块首先使用它；未来工具能力会继续挂载到同一版本化配置。</p></div><span className="agent-state is-ready">{behaviorVersion?`已激活 · v${behaviorVersion}`:'读取中'}</span></div><div className="agent-settings-grid"><label className="is-wide">核心使命<textarea rows="3" maxLength="1200" value={behavior.core.mission} onChange={event=>setCore('mission',event.target.value)}/><small>决定机器人长期关注什么，但不能覆盖安全、权限和引用规则。</small></label><label>性格<textarea rows="4" maxLength="1200" value={behavior.core.personality} onChange={event=>setCore('personality',event.target.value)}/></label><label>表达风格<textarea rows="4" maxLength="800" value={behavior.core.voice} onChange={event=>setCore('voice',event.target.value)}/></label><label className="is-wide">目标读者<textarea rows="2" maxLength="500" value={behavior.core.audience} onChange={event=>setCore('audience',event.target.value)}/></label><label className="is-wide">选题编辑人格<textarea rows="5" maxLength="1600" value={behavior.modules.editorial.persona} onChange={event=>setEditorial('persona',event.target.value)}/><small>AI 会用这段人格在合格候选之间自主竞争，无需运营人员逐篇确认。</small></label><label className="is-wide">兴趣信号（每行一个）<textarea rows="6" value={behavior.modules.editorial.interestSignals.join('\n')} onChange={event=>setEditorial('interestSignals',event.target.value.split(/\r?\n/u).map(item=>item.trim()).filter(Boolean).slice(0,12))}/><small>这些是编辑偏好，不是事实来源；候选仍必须通过客观门槛。</small></label><label className="agent-switch"><input type="checkbox" checked={behavior.modules.editorial.comparisonEnabled} onChange={event=>setEditorial('comparisonEnabled',event.target.checked)}/><span>允许 AI 在同类项目之间自动选择对比文章</span></label></div><footer><button className="button button--primary" disabled={!!busy||!behaviorVersion} onClick={saveBehavior}>{busy==='behavior'?'保存新版本中…':'保存并激活人格新版本'}</button><small>每次保存创建不可变的新版本；运行记录会保留所用版本。</small></footer></section>
        <section className="agent-control-card"><div className="agent-control-card__title"><div><span className="kicker">PROVIDER SECRET</span><h3>模型供应商 Key</h3></div><span className={selected.providerKey.configured?'agent-state is-ready':'agent-state'}>{selected.providerKey.configured?`已配置 ····${selected.providerKey.lastFour}`:'未配置'}</span></div><p>Key 在服务器端验证后加密保存；已保存明文不会返回浏览器。</p><div className="agent-key-row"><input type="password" autoComplete="new-password" value={apiKey} onChange={event=>setApiKey(event.target.value)} placeholder={selected.providerKey.configured?'输入新 Key 可轮换':'输入 DeepSeek API Key'}/><button className="button button--primary" disabled={!!busy||apiKey.trim().length<16} onClick={saveKey}>{busy==='key'?'验证中…':selected.providerKey.configured?'验证并轮换':'验证并保存'}</button>{selected.providerKey.configured&&<button className="danger-button" disabled={!!busy} onClick={()=>globalThis.confirm?.('删除 Key 会同时暂停自动发布。确定继续？')&&action('delete-key',()=>api.deleteAdminAgentProviderKey(selected.agentUserId))}>删除 Key</button>}</div></section>
        <section className="agent-control-card agent-publication-card"><div className="agent-control-card__title"><div><span className="kicker">PUBLICATION OWNERSHIP</span><h3>公开发布权</h3><p>同一时刻只有一条链路能公开文章。新基座接管后，旧流程会从日常管理面退役。</p></div><span className={publicationIsFoundation?'agent-state is-ready':'agent-state'}>{cutover.status==='loading'?'读取中…':publicationOwner?`${publicationIsFoundation?'新基座':'旧流程'} · 第 ${publicationOwner.generation} 代`:'状态未知'}</span></div>{cutover.status==='error'?<p className="form-error" role="alert">{cutover.error}</p>:cutover.status==='loading'?<p className="agent-empty" role="status">正在核对发布权与切换证据…</p>:publicationOwner&&<><div className="agent-publication-grid"><div><small>当前唯一发布者</small><strong>{publicationIsFoundation?'新 Foundation 基座':'旧自动发布流程'}</strong><span>{publicationOwner.reason||'尚无切换说明'}</span></div><div><small>私有草稿验收</small><strong>{publicationEvidence?.acceptanceConsecutivePasses??0}/{publicationEvidence?.requiredAcceptancePasses??1}</strong><span>至少一份完整自动验收</span></div><div><small>定时运行</small><strong>{publicationIsFoundation?'新基座独立管理':'切换后独立启用'}</strong><span>不伪造记录，也不要求等待三个自然日</span></div><div><small>运行安全</small><strong>{(publicationEvidence?.legacyActiveRuns??0)+(publicationEvidence?.foundationActiveRuns??0)+(publicationEvidence?.foundationUncertainRuns??0)===0?'没有未完成任务':'仍有任务未结束'}</strong><span>旧 {publicationEvidence?.legacyActiveRuns??0} · 新 {publicationEvidence?.foundationActiveRuns??0} · 待确认 {publicationEvidence?.foundationUncertainRuns??0}</span></div></div>{publicationIsFoundation?<div className="agent-publication-readiness is-ready"><strong>旧流程已下线</strong><span>旧调度、旧手动运行和旧记录入口已退出主控制台；历史文章与审计证据只读保留。</span></div>:<><div className={cutover.data.ready?'agent-publication-readiness is-ready':'agent-publication-readiness'}><strong>{cutover.data.ready?'已满足切换条件':'暂时不能切换'}</strong>{cutover.data.ready?<span>私有端到端验收和确定性门禁均已通过；仍需管理员明确确认。</span>:<ul>{cutover.data.blockers.map(code=><li key={code}>{cutoverBlockerLabel[code]||code}</li>)}</ul>}</div><label className="agent-publication-reason">操作原因<textarea rows="3" maxLength="500" value={cutoverReason} onChange={event=>setCutoverReason(event.target.value)} placeholder="说明为什么现在可以将公开发布权交给新基座"/><small className={cutoverReason.length>0&&!publicationReasonReady?'is-error':''}>{cutoverReason.trim().length}/500；至少 10 个字符，原因会进入审计记录。</small></label><footer><button type="button" className="button button--secondary" disabled={cutover.status==='loading'||!!busy} onClick={()=>loadCutover(selected.agentUserId)}>重新预检</button><button type="button" className="button button--primary" disabled={!!busy||!cutover.data.ready||!publicationReasonReady} onClick={()=>changePublicationOwner('cutover')}>{busy==='publication-cutover'?'正在切换…':'将发布权切换到新基座'}</button><small>切换会停用旧流程与私有计划；公开计划仍保持关闭。</small></footer></>}</>}</section>
        <section className="agent-control-card agent-public-operations"><div className="agent-control-card__title"><div><span className="kicker">PUBLIC OPERATIONS</span><h3>新基座自动运行</h3><p>在后台管理同一台服务器上的公开计划。所有操作仍会经过身份、预算、发布权和运行状态预检。</p></div><span className={publicSchedulerOnline?'agent-state is-ready':'agent-state'}>{!publicOperations?'读取中…':publicSchedulerOnline?'每天 10 点在线':publicOperations.manualRun.ready?'执行器已就绪':'尚未就绪'}</span></div>{publicOperations?<><div className="agent-operations-grid"><div><small>立即运行</small><strong>{publicOperations.manualRun.ready?'可以执行':publicQuotaSpent?'今日已完成':'暂不可运行'}</strong><span>{publicQuotaSpent?'今天已成功公开一篇；下一次将于明天 10 点自动执行。':'点击后把下一次任务安全提前到现在，由持久调度器领取。'}</span></div><div><small>定时执行器</small><strong>{publicOperations.scheduler.configured?'服务器已配置':'服务器未启用'}</strong><span>{publicOperations.scheduler.workerLive?`心跳 ${format(publicOperations.scheduler.heartbeatAt)}`:'没有可确认的在线心跳'}</span></div><div><small>公开计划</small><strong>{publicOperations.scheduler.timezone} {publicOperations.scheduler.localTime}</strong><span>{runtimeOverview?.schedule?.enabled?`下次 ${format(runtimeOverview.schedule.nextFireAt)}`:'当前已暂停'}</span></div><div><small>费用与运行上限</small><strong>{publicOperations.observed.providerCallsMonth}/{publicOperations.limits.monthlyProviderCalls} 次模型调用</strong><span>本月费用 {publicOperations.observed.costMicrousdMonth}/{publicOperations.limits.monthlyCostMicrousd} 微美元 · 今日已发布 {publicOperations.observed.publicationRunsToday}/{publicOperations.limits.dailyPublicationRuns} · GitHub研究 {publicOperations.observed.githubResearchAuthenticated?'已认证':'未认证'}，每次最多 {publicOperations.limits.githubCandidateLimit} 个候选 / {publicOperations.limits.githubRequestBudgetPerRun} 次请求</span></div></div>{actionablePublicBlockers.length>0&&<div className="agent-operations-blockers"><strong>仍需处理</strong><ul>{[...new Set(actionablePublicBlockers)].map(code=><li key={code}>{publicRuntimeBlockerLabel[code]||code}</li>)}</ul></div>}<footer><button type="button" className="button button--primary" disabled={!!busy||!publicOperations.manualRun.ready} onClick={runFoundationNow}>{busy==='foundation-run'?'正在加入队列…':'立即运行新基座'}</button>{runtimeOverview?.schedule?.enabled?<button type="button" className="button button--secondary" disabled={!!busy} onClick={()=>setPublicSchedule(false)}>{busy==='public-schedule-disable'?'正在暂停…':'暂停每天 10 点'}</button>:<button type="button" className="button button--secondary" disabled={!!busy||!publicOperations.scheduler.configured||!publicOperations.manualRun.ready} onClick={()=>setPublicSchedule(true)}>{busy==='public-schedule-enable'?'正在启用…':'启用每天 10 点'}</button>}<button type="button" className="button button--secondary" onClick={()=>loadRuns(selected.agentUserId)}>刷新状态</button><small>容器仍由部署流程管理；日常启停、恢复和立即运行都在这里完成。</small></footer></>:<p className="agent-empty" role="status">正在核对公开执行条件…</p>}</section>
        {!publicationIsFoundation&&<section className="agent-control-card"><div className="agent-control-card__title"><div><span className="kicker">LEGACY AUTOPILOT</span><h3>旧自动发布策略</h3><p>仅用于切换前兼容；新基座取得发布权后自动从管理界面移除，避免同时操作两套流程。</p></div><label className="agent-switch"><input type="checkbox" checked={settings.enabled} onChange={event=>setSettings(current=>({...current,enabled:event.target.checked}))}/><span>{settings.enabled?'已启用':'已暂停'}</span></label></div><div className="agent-settings-grid"><label className="agent-model-field">模型<div className="agent-model-picker"><select value={settings.model} disabled={!selected.providerKey.configured||modelsState==='loading'||!models.length} onChange={event=>setSettings(current=>({...current,model:event.target.value}))}>{!models.some(model=>model.id===settings.model)&&<option value={settings.model}>{settings.model}</option>}{models.map(model=><option key={model.id} value={model.id}>{modelLabel(model)}</option>)}</select><button type="button" className="button button--secondary" disabled={!selected.providerKey.configured||modelsState==='loading'||!!busy} onClick={()=>loadModels(selected.agentUserId)}>{modelsState==='loading'?'同步中…':'刷新模型'}</button></div><small className={modelsState==='error'?'is-error':''}>{modelHint}</small></label><label>发布间隔<select value={settings.intervalHours} onChange={event=>setSettings(current=>({...current,intervalHours:Number(event.target.value)}))}><option value="24">每天 10:00（北京时间）</option><option value="84">每周约 2 篇</option><option value="168">每周 1 篇</option><option value="336">每两周 1 篇</option></select><small>旧流程每天模式会在北京时间 10:00 进入写作与发布队列。</small></label><label>每月运行上限<input type="number" min="1" max="100" value={settings.monthlyArticleLimit} onChange={event=>setSettings(current=>({...current,monthlyArticleLimit:Number(event.target.value)}))}/><small className={settings.intervalHours===24&&settings.monthlyArticleLimit<31?'is-error':''}>{settings.intervalHours===24&&settings.monthlyArticleLimit<31?'每天运行需将上限设为 31；当前上限会在月内提前停止。':'失败和检查拒绝也计入，用于限制模型费用。'}</small></label><label className="is-wide">选题范围<textarea rows="4" maxLength="1000" aria-invalid={topicScopeLength<AGENT_TOPIC_SCOPE_MIN_LENGTH} value={settings.topicScope} onChange={event=>setSettings(current=>({...current,topicScope:event.target.value}))}/><small className={topicScopeLength<AGENT_TOPIC_SCOPE_MIN_LENGTH?'is-error':''}>{topicScopeLength}/1000；至少填写 {AGENT_TOPIC_SCOPE_MIN_LENGTH} 个字符，例如“人工智能与大众科技知识”。</small></label></div><footer><button className="button button--primary" disabled={!!busy||modelsState==='loading'||(settings.enabled&&!models.some(model=>model.id===settings.model))} onClick={saveSettings}>{busy==='settings'?'保存中…':'保存旧流程策略'}</button><button className="button button--secondary" disabled={!!busy||!selected.providerKey.configured} onClick={()=>action('run',()=>api.runAdminAgentBlogNow(selected.agentUserId))}>{busy==='run'?'排队中…':'运行旧流程一次'}</button><small>旧流程下次计划：{format(selected.automation.nextRunAt)}</small></footer></section>}
        <section className="agent-control-card agent-run-history agent-runtime-history"><div className="agent-control-card__title"><div><span className="kicker">FOUNDATION RUNTIME</span><h3>{publicationIsFoundation?'公开与研究运行':'新基座运行'}</h3><p>{publicationIsFoundation?'展示新基座接管后的公开运行，以及与公开发布隔离的私有论文研究。':'统一展示候选发现、私有草稿、影子验收与私有论文研究；每条记录都保留阶段与来源链路。'}</p></div><div className="agent-runtime-overview"><span className={publicationIsFoundation||runtimeOverview?.acceptance.readyForShadowScheduleReview?'agent-state is-ready':'agent-state'}>{publicationIsFoundation?'公开链路':`影子验收 ${runtimeOverview?.acceptance.consecutivePasses??'—'}/${runtimeOverview?.acceptance.requiredConsecutivePasses??3}`}</span><small>{runtimeOverview?.schedule?.suspendedAt?`调度已停用 · ${runtimeOverview.schedule.suspensionReason||'等待排查'}`:runtimeOverview?.schedule?.enabled?`下次 ${format(runtimeOverview.schedule.nextFireAt)}`:'新调度尚未启用'}</small><button type="button" className="button button--secondary" onClick={()=>loadRuns(selected.agentUserId)}>刷新</button></div></div>{visibleRuntimeRuns.length?<ol>{visibleRuntimeRuns.map(run=>{const detail=runtimeDetails[run.id],draft=run.foundationDraft,semantic=run.paperSemanticAnalysis,acceptance=run.acceptance,isPublicRun=run.workflowKey==='blog.project.single',isPaperRun=['paper.single.semantic-shadow','paper.private.research'].includes(run.workflowKey),isPaperFollowUp=run.workflowKey==='paper.semantic.follow-up-private',workflow=runtimeWorkflowLabel[run.workflowKey]||run.workflowKey,summary=isPaperFollowUp?(run.status==='succeeded'?'私有证据追问已核验并写入不可变问答账本；未联网、未发布。':run.errorMessage||run.errorCode||'正在冻结论文分析、生成回答并核验引用。'):isPaperRun?(semantic?`私有语义分析已完成：${semantic.findingCount} 个结论节点、${semantic.limitationCount} 项局限；未尝试公开发布。`:run.errorMessage||run.errorCode||'正在获取合法全文，执行论文准入、证据重建和语义核验。'):draft?(isPublicRun?(draft.publicationState==='published'?'文章已由新基座公开发布并写入不可变发布回执。':run.errorMessage||run.errorCode||'公开文章流程已生成内容，但尚未完成发布。'):acceptance?.verdict==='passed'?'影子验收已通过；草稿保持私有，未尝试发布。':acceptance?.verdict==='failed'?`影子验收未通过：${acceptance.reasonCodes.join(' · ')}`:'私有草稿已生成，等待影子验收。'):(run.errorMessage||run.errorCode||(run.status==='succeeded'?'候选清单已交接给下游运行。':'新基座流程处理中。'));return <li key={run.id} className={`is-${run.status}`}><span className="agent-run-dot"/><div><div className="agent-runtime-title"><strong>{semantic?.title||draft?.title||workflow}</strong><span className={`agent-runtime-badge is-${acceptance?.verdict||run.status}`}>{acceptance?.verdict==='passed'?'验收通过':acceptance?.verdict==='failed'?'验收失败':runtimeStatusLabel[run.status]||run.status}</span></div><p>{summary}</p><small>{workflow} · 阶段 {run.completedStageCount}/{run.stageCount} · 动作 {run.actionCount}</small><small>{format(run.startedAt||run.queuedAt)} · 运行 {run.id.slice(0,8)}{run.sourceRunId?` · 来源 ${run.sourceRunId.slice(0,8)}`:''}</small></div><div className="agent-run-actions">{isPublicRun&&draft?.slug&&draft.publicationState==='published'?<button className="button button--primary" onClick={()=>go(`/blog/${draft.slug}`)}>查看文章</button>:draft?.articleId&&<button className="button button--primary" onClick={()=>openFoundationDraft(draft.articleId)}>查看草稿</button>}<button className="button button--secondary" onClick={()=>toggleRuntimeDetails(run)}>{detail?.expanded?'收起阶段':'查看阶段'}</button></div>{detail?.expanded&&<div className="agent-runtime-detail">{detail.status==='loading'?<p>正在读取完整阶段记录…</p>:detail.status==='error'?<p className="form-error">{detail.error}</p>:<><ol>{detail.data.stages.map(stage=><li key={stage.id} className={`is-${stage.status}`}><span>{stage.ordinal}</span><div><strong>{runtimeStageLabel[stage.stageKey]||stage.stageKey}</strong><small>{runtimeStatusLabel[stage.status]||stage.status}{stage.attempt>1?` · 第 ${stage.attempt} 次尝试`:''}{stage.errorCode?` · ${stage.errorCode}`:''}{stage.status==='queued'&&stage.availableAt?` · 下次尝试 ${format(stage.availableAt)}`:''}</small></div></li>)}</ol><CandidateGateReport report={detail.data.candidateGate}/>{detail.data.paperSemanticAnalyses?.map(item=><section className="agent-paper-semantic-detail" key={item.id}><header><strong>私有结论—证据图</strong><span>{item.provider} · {item.modelId}</span></header><p>{item.findings.length} 个结论节点 · {item.evidenceRelationCount} 条证据关系 · {item.limitations.length} 项局限</p><small>不可变摘要 {item.analysisSha256.slice(0,12)}… · 不具备公开发布权限</small></section>)}</>}</div>}</li>})}</ol>:<p className="agent-empty">尚无新基座运行；公开发布权、研究门禁和调度状态见上方控制卡。</p>}</section>
        {!publicationIsFoundation&&<section className="agent-control-card agent-run-history"><div className="agent-control-card__title"><div><span className="kicker">LEGACY AUDIT LEDGER</span><h3>旧自动发布记录</h3><p>仅用于切换前的运营和核对；新基座接管后不再加载这套旧入口。</p></div><button type="button" className="button button--secondary" onClick={()=>loadRuns(selected.agentUserId,true)}>刷新</button></div>{runs.length?<ol>{runs.map(run=>{const selection=run.providerUsage?.selectionDecision;return <li key={run.id} className={`is-${run.status}`}><span className="agent-run-dot"/><div><strong>{run.articleTitle||statusLabel[run.status]||run.status}</strong><p>{run.status==='published'?(run.withdrawnAt?'文章已由管理员撤回。':selection?.rationale||'已通过旧流程自动检查并公开发布。'):run.errorMessage||run.reasonCodes.join(' · ')||'旧自动流程处理中。'}</p>{selection&&<small>{selection.mode==='comparison'?'对比文章':'单项目文章'} · {selection.repositories.join('、')}</small>}<small>{format(run.startedAt||run.createdAt)} · {run.model}{run.behaviorProfileVersion?` · 人格 v${run.behaviorProfileVersion}`:''}</small></div><div className="agent-run-actions">{run.articleSlug&&!run.withdrawnAt&&<button className="button button--secondary" onClick={()=>go(`/blog/${run.articleSlug}`)}>查看文章</button>}{run.articleId&&!run.withdrawnAt&&<button className="danger-button" disabled={!!busy} onClick={()=>globalThis.confirm?.('撤回后公众将无法访问这篇旧流程发布的文章。确定继续？')&&action(`withdraw-${run.id}`,()=>api.withdrawAdminAgentBlogArticle(selected.agentUserId,run.id))}>撤回</button>}</div></li>})}</ol>:<p className="agent-empty">尚无旧自动发布记录。</p>}</section>}
        <PaperResearchOperationsCard api={api} agentUserId={selected.agentUserId}/>
        <PaperResearchLifecycleCard api={api} agentUserId={selected.agentUserId}/>
        <PaperIntakeCard api={api} agentUserId={selected.agentUserId}/>
        <PaperDiscoveryCard api={api} agentUserId={selected.agentUserId}/>
        <PaperQualityCard data={runtimeOverview?.paperResearch} onOpenFollowUp={openPaperFollowUp}/>
      </main>}
    </div>}
    {draftPreview&&<DraftPreview state={draftPreview} onClose={()=>setDraftPreview(null)}/>}
    {paperFollowUp&&<PaperFollowUpDialog state={paperFollowUp} onClose={()=>setPaperFollowUp(null)} onAsk={askPaperFollowUp}/>}
  </section>;
}
